config.command:
set -eu
N="${NARU_HOME:-${MESA_HOME:-}}"; [ -n "$N" ] || { N="$HOME/.naru"; [ ! -e "$N" ] && [ -e "$HOME/.mesa" ] && N="$HOME/.mesa"; }
D=$(cat "$N/kb-cleanup/current"); . "$D/settings.env"
KB="${NARU_KB_DIR:-${MESA_KB_DIR:-$N/kb}}"
HAIKU() { (mkdir -p "$N/workspace" && cd "$N/workspace" && claude -p --model haiku --tools "" --strict-mcp-config --no-session-persistence --output-format text 2>/dev/null); }

# Moves bypass the kb writer, so regenerate INDEX.md (topics/t/s.md | title | tags | updated) from the notes.
[ -s "$D/moves-done.tsv" ] || { echo "no moves, index untouched"; exit 0; }
naru kb list | jq -r '.[]|[.path,.title,(.tags|join(", ")),.updated]|join(" | ")' > "$KB/INDEX.md.new" && mv "$KB/INDEX.md.new" "$KB/INDEX.md"
echo "index rebuilt: $(wc -l < "$KB/INDEX.md" | tr -d ' ') lines"
